import React, { useEffect } from 'react';
import useChat from './useChat';
import ChatRoom from './ChatRoom';

const GeneralChat = () => {
    // Доступные комнаты чата
    const availableRooms = [
        { id: 'user1', label: 'Новички' },
        { id: 'user2', label: 'Продвинутые' }
    ];

    // Названия комнат
    const roomTitles = {
        user1: 'Чат',
        user2: 'Чат продвинутых'
    };

    const {
        messages,
        loading,
        currentRoom,
        canSwitch,
        currentUserAuthor,
        isRecording,
        recordingTime,
        changeRoom,
        sendMessage,
        editMessage,
        deleteMessage,
        uploadFile,
        startRecording,
        stopRecording,
        loadMessages
    } = useChat('user1', {
        storageKeyPrefix: 'generalChatMessages',
        canSwitchRooms: true,
        availableRooms
    });

    // Настройка прав доступа на основе роли
    useEffect(() => {
        const demoRole = localStorage.getItem('demoRole');
        // user_1 может только читать чат новичков (user1)
        // user_2 и выше могут переключаться
    }, []);

    if (loading) return <div className="loading">Загрузка чата...</div>;

    return (
        <ChatRoom
            messages={messages}
            currentUserAuthor={currentUserAuthor}
            currentRoom={currentRoom}
            canSwitch={canSwitch}
            availableRooms={availableRooms}
            roomTitles={roomTitles}
            onRoomChange={changeRoom}
            onSendMessage={sendMessage}
            onEditMessage={editMessage}
            onDeleteMessage={deleteMessage}
            onFileUpload={uploadFile}
            onStartRecording={startRecording}
            onStopRecording={stopRecording}
            isRecording={isRecording}
            recordingTime={recordingTime}
        />
    );
};

export default GeneralChat;
